const j=$input.first().json;
if(!j.job_exists) throw new Error(`Job ${j.requested_job_id} was not found`);
if(!j.eligible) throw new Error(`Job ${j.job_id} is not eligible for planning: ${j.status}/${j.current_stage}`);
const supported=new Set(['en','pl','ru','uk']);
if(!supported.has(j.language_code)) throw new Error(`Unsupported language: ${j.language_code}`);
const counts={15:6,30:10,45:14,60:18};
if(!counts[Number(j.target_duration_seconds)]) throw new Error(`Unsupported duration: ${j.target_duration_seconds}`);
return [{json:{job_id:j.job_id,topic:String(j.topic??'').trim(),language_code:j.language_code,target_duration_seconds:Number(j.target_duration_seconds)}}];

const j=$input.first().json;
const topic=String(j.topic??'').normalize('NFKC').replace(/\s+/gu,' ').trim();
const language=String(j.language_code??'').trim().toLowerCase();
const names={en:'English',pl:'Polish',ru:'Russian',uk:'Ukrainian'};
if(!topic)throw new Error('topic is empty');if(!names[language])throw new Error('unsupported language');
const prompt=`You generate candidate interpretations for the semantic intake stage of an autonomous short-video system. The input may be a person, fictional character, company, object, event, phenomenon, question, colloquial name, transliteration, or short ambiguous term. The language of the topic is independent from the selected output language. Do not choose a winner yet.

RAW TOPIC: ${topic}
SELECTED OUTPUT LANGUAGE: ${names[language]} (${language})

Return ONLY valid JSON with this exact shape:
{"topic_language":"...","topic_kind":"entity|question|concept|event|other","candidates":[{"candidate_id":"C1","canonical_name":"...","subject_type":"...","context":"...","interpretation":"...","discovery_query":"..."}]}

Rules:
- Produce 2-5 genuinely distinct plausible meanings when the topic is ambiguous; for a clear question or subject, produce one primary interpretation plus any materially plausible alternative alternative, if one exists.
- Consider translations, transliterations, aliases, fictional and real-world meanings, and common usage.
- Do not promote a longer lexical lookalike merely because it contains the raw string.
- discovery_query must be an English web query that can independently test that candidate.
- candidate_id values must be C1, C2, ... and unique.
- Do not answer the topic and do not claim a winner without search evidence.`;
return [{json:{...j,raw_topic:topic,output_language_name:names[language],intent_prompt:prompt}}];

const candidateItems=$('Parse Semantic Intent').all().map(x=>x.json);const discoveryItems=$input.all().map(x=>x.json);if(!candidateItems.length||candidateItems.length!==discoveryItems.length)throw new Error('candidate discovery result count mismatch');const base=candidateItems[0];const candidates=base.semantic_candidates;const evidence=[];for(let i=0;i<candidateItems.length;i++){const cid=candidateItems[i].candidate_id;const rows=(Array.isArray(discoveryItems[i].results)?discoveryItems[i].results:[]).slice(0,6);for(let k=0;k<rows.length;k++){const x=rows[k];const title=String(x.title??'').replace(/\s+/gu,' ').trim(),snippet=String(x.content??x.description??'').replace(/\s+/gu,' ').trim(),url=String(x.url??'').trim();if(title&&snippet&&url)evidence.push({evidence_id:`D-${cid}-${k+1}`,candidate_id:cid,title,snippet,url});}}if(evidence.length<2)throw new Error('semantic discovery returned fewer than two usable results');const candidateText=candidates.map(c=>`${c.candidate_id} | ${c.canonical_name} | ${c.subject_type} | ${c.context}
Interpretation: ${c.interpretation}
Query: ${c.discovery_query}`).join('

');const evidenceText=evidence.map(x=>`${x.evidence_id} | candidate ${x.candidate_id} | ${x.title}
${x.snippet}
${x.url}`).join('

');const prompt=`You resolve the intended meaning of a raw user topic for an autonomous research pipeline. Compare all candidate interpretations against the raw wording, linguistic/common-usage plausibility, and supplied independent web-search evidence. Search rank alone and lexical substring similarity are not proof of intent.

RAW TOPIC: ${base.raw_topic}
TOPIC LANGUAGE (estimated): ${base.topic_language}
TOPIC KIND: ${base.topic_kind}

CANDIDATES:
${candidateText}

DISCOVERY EVIDENCE:
${evidenceText}

Return ONLY valid JSON with this exact shape:
{"selected_candidate_id":"C1","resolved_subject":"...","canonical_name":"...","subject_type":"...","context":"...","user_intent":"...","research_query_en":"...","confidence":0.0,"runner_up_candidate_id":"C2|null","score_margin":0.0,"reasoning_evidence_ids":["D-C1-1"],"resolution_reason":"..."}

Rules:
- Select the meaning a reasonable user most likely intended, not merely the result with the closest spelling or largest search presence.
- Prefer exact/common names and direct translations or transliterations over longer lexical lookalikes.
- For questions, preserve the question intent rather than forcing an entity.
- reasoning_evidence_ids must cite 1-6 supplied evidence IDs and support the selected meaning.
- confidence and score_margin must be numbers from 0 to 1.
- research_query_en must unambiguously research the selected meaning.
- Do not add facts not present in the candidate/evidence inventory.`;return [{json:{...base,discovery_evidence:evidence,resolution_prompt:prompt}}];

const incoming=$input.first()?.json??{};
let jobId=String(incoming.job_id??incoming.requested_job_id??'').trim();
const recover=(name)=>{try{return String($(name).first().json?.job_id??$(name).first().json?.requested_job_id??'').trim()}catch{return ''}};
if(!jobId){for(const name of ['Build Final Inventory Story','Prepare Inventory Grounded Story','Select Verified Claim Inventory','Validate Candidate Claims','Prepare Candidate Claims','Draft Candidate Claims','Parse Semantic Intent','Prepare Semantic Intent','Require Eligible Job','Load Eligible Job','Receive Job ID']){jobId=recover(name);if(jobId)break;}}
let message='';const e=incoming.error;if(typeof e==='string')message=e;else if(e&&typeof e==='object')message=String(e.message??e.description??e.cause??'');if(!message)message=String(incoming.message??incoming.error_message??'');if(!message){try{message=JSON.stringify(incoming)}catch{message='WF02 failed'}};message=message.slice(0,4000);if(!jobId)throw new Error('WF02 failure handler could not recover job_id');return [{json:{job_id:jobId,error_message:message}}];

const j=$('Validate Resolved Topic').first().json;const r=$input.first().json;const clean=v=>String(v??'').normalize('NFKC').replace(/\s+/gu,' ').trim();let rows=(Array.isArray(r.results)?r.results:[]).slice(0,10).map((x,i)=>({id:`S${i+1}`,title:clean(x.title),snippet:clean(x.content??x.description),url:clean(x.url)})).filter(x=>x.title&&x.snippet&&x.url);if(rows.length<2){const seen=new Set(rows.map(x=>x.url));for(const x of (Array.isArray(j.discovery_evidence)?j.discovery_evidence:[])){const title=clean(x.title),snippet=clean(x.snippet),url=clean(x.url);if(title&&snippet&&url&&!seen.has(url)){rows.push({id:`S${rows.length+1}`,title,snippet,url});seen.add(url);}if(rows.length>=10)break;}}if(rows.length<2)throw new Error('combined research returned fewer than two usable results');const target=Number(j.target_duration_seconds),range={15:[4,6],30:[6,8],45:[8,10],60:[10,12]}[target];if(!range)throw new Error('unsupported duration');const evidence=rows.map(x=>`${x.id} | ${x.title}
${x.snippet}
${x.url}`).join('

');const prompt=`Create candidate FACTUAL CLAIMS for an autonomous short-video story. Do NOT write the final narration yet.

RAW TOPIC: ${j.topic}
RESOLVED SUBJECT: ${j.resolved_subject}
CANONICAL NAME: ${j.canonical_subject}
USER INTENT: ${j.user_intent}
TARGET DURATION: ${target}s

RESEARCH:
${evidence}

Return ONLY JSON {"claims":[{"claim_id":"C1","claim":"one complete factual proposition in English","evidence_ids":["S1"],"visual_target":"one concrete English still-image target","search_query_en":"short subject and detail keywords"}]}.
Requirements: ${range[0]}-${range[1]} claims; claim IDs C1..Cn in order; every claim must be directly supported by every cited evidence ID and cite 1-3 IDs from the research above; do not merge unrelated facts into one claim; visual_target must literally depict the claim using a realistically obtainable photo, historical image, technical diagram, scientific illustration, real person, place, object or mechanism; define only the minimum observable subject and distinguishing feature needed to support the claim; do not invent camera angles, background landmarks, dates, side-by-side arrangements or simultaneous actions unless they are essential to the claim; a still photo cannot reveal hidden internals, changes over time or a numerical measurement without visible evidence: choose a supported claim about an observable component or an explanatory diagram instead; prioritize claims that answer the user intent rather than peripheral historical trivia; search_query_en must be 2-8 English search keywords, at most 90 characters: preserve the named subject plus the distinguishing object, part, mechanism or media type; never send the full visual description as a search query and never use just the overall topic for every claim; visual_target remains the full acceptance criterion and must not be relaxed to match search results; avoid abstract concepts, title cards, generic filler, logos, screenshots and named copyrighted scenes; prefer a different truthful visual subject for each claim; do not invent a claim merely because an image might exist.`;return [{json:{...j,research_rows:rows,candidate_claim_range:range,claim_prompt:prompt}}];

const x=$input.first().json,clean=v=>String(v??'').normalize('NFKC').replace(/\s+/gu,' ').trim(),bounds=x.story_unit_bounds;if(!Array.isArray(bounds)||bounds.length!==2)throw new Error('story unit bounds missing');const rowMap=new Map(x.research_rows.map(r=>[r.id,r]));const inventory=x.verified_claims.map(c=>{const evidence=c.evidence_ids.map(id=>{const r=rowMap.get(id);return `${id}: ${r?.snippet??''}`}).join(' | ');return `${c.claim_id} | FACT: ${c.claim}
EVIDENCE: ${evidence}
VISIBLE ASSET ${c.asset.asset_id}: ${c.asset.visible_description}
VISUAL TARGET: ${c.visual_target}`}).join('

');const words={15:[30,42],30:[62,82],45:[95,122],60:[128,165]}[Number(x.target_duration_seconds)];const prompt=`Write the FINAL spoken short-video story using ONLY the verified claims below. Every selected unit already has a verified real image reserved before narration.

TOPIC: ${x.topic}
RESOLVED SUBJECT: ${x.canonical_subject}
USER INTENT: ${x.user_intent}
OUTPUT LANGUAGE: ${x.output_language_name} (${x.language_code})
TARGET: ${x.target_duration_seconds}s, approximately ${words[0]}-${words[1]} spoken words
SELECT ${bounds[0]}-${Math.min(bounds[1],x.verified_claims.length)} units.

VERIFIED CLAIM + IMAGE INVENTORY:
${inventory}

Return ONLY JSON {"units":[{"claim_id":"C1","narration":"complete spoken sentence(s) in the selected output language"}]}. Rules: each claim_id may appear at most once and must come from the inventory; choose a coherent truthful story, not a list; narration for a unit may paraphrase only that claim and its evidence, add no new factual assertion; each unit must be a complete semantic thought and must not end in a fragment; answer the user intent immediately; use natural spoken prose; no headings, citations, slash separators, pipes, arrows, bullets or markdown; do not mention images or sources.`;return [{json:{...x,story_prompt:prompt,target_word_min:words[0],target_word_max:words[1]}}];

const item=$json;
const model_request={ prompt: item.claim_prompt, temperature: 0.15, response_format: 'json', response_schema: {"type":"object","properties":{"claims":{"type":"array","items":{"type":"object","properties":{"claim_id":{"type":"string"},"claim":{"type":"string"},"evidence_ids":{"type":"array","items":{"type":"string"}},"visual_target":{"type":"string"},"search_query_en":{"type":"string"}},"required":["claim_id","claim","evidence_ids","visual_target","search_query_en"]}}},"required":["claims"]} };
return {json:{...item,model_request}};

const item=$json;
const model_request={ input: item.input, response_format: 'json', response_schema: { type: 'object', properties: { claims: { type: 'array', items: { type: 'object', properties: { claim_number: { type: 'integer' }, verdicts: { type: 'array', items: { type: 'object', properties: { review_id: { type: 'string' }, relevant: { type: 'boolean' }, visible_description: { type: 'string' }, supported_claim: { type: 'string' }, supported_evidence_ids: { type: 'array', items: { type: 'string' } } }, required: ['review_id','relevant','visible_description','supported_claim','supported_evidence_ids'] } } }, required: ['claim_number','verdicts'] } } }, required: ['claims'] } };
return {json:{...item,model_request}};

