const model_request={ prompt: item.story_prompt, temperature: 0.15, response_format: 'json', response_schema: {"type":"object","properties":{"units":{"type":"array","items":{"type":"object","properties":{"claim_id":{"type":"string"},"narration":{"type":"string"}},"required":["claim_id","narration"]}}},"required":["units"]} };
